    # while each isolated signal pixel becomes a 4 endpoint.
    # Identify edge-connected runs of non-background cells.
    left = [r for r in range(h) if grid[r][0] != bg]
    right = [r for r in range(h) if grid[r][-1] != bg]
    top = [c for c in range(w) if grid[0][c] != bg]
    bottom = [c for c in range(w) if grid[-1][c] != bg]
