 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Markers project their color to the opposite edge from the adjacent edge bar.
    for r in range(h):
        for c, v in enumerate(grid[r]):
            if v not in (grid[0][0], 0):
                out[r][c] = 4
                if grid[r][0] == 0:
                    for j in range(c+1, w): out[r][j] = v
                elif grid[r][-1] == 0:
                    for j in range(0, c): out[r][j] = v
    return out
