{
 "path": "programs/task-cc637199.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The edge markers are the only changes: for each interior 7, extend
    # its color back toward the edge and turn the marker into endpoint 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7:
                for j in range(1, c):
                    out[r][j] = 7
                out[r][c] = 4
    return out
"
}
